from scipy.ndimage import label

def solve(I):
    I=np.array(I); H,W=I.shape
    cnt={int(v):int(np.sum(I==v)) for v in np.unique(I)}
    frame=int(max(cnt,key=lambda v:cnt[v]))
    lab,_=label(I==frame)
    comp=max(range(1,np.max(lab)+1), key=lambda k:int((lab==k).sum()))
    fb=[(r,c) for r,c in np.argwhere(lab==comp)]
    out=np.full((H,W),frame,dtype=int)
    for r,c in fb: out[r,c]=frame
    obj_colors=[int(v) for v in cnt if v!=frame]
    # bands: contiguous runs of rows that contain any object color
    rowhas=[any(I[r,c] in {v for v in obj_colors} for c in range(W)) for r in range(H)]
    bands=[]; cur=None
    for r,h in enumerate(rowhas):
        if h and cur is None: cur=[r]
        elif h and cur[-1]+1==r: cur.append(r)
        else:
            if cur: bands.append(cur); cur=None
    if cur: bands.append(cur)
    for ocol in sorted(obj_colors):
        ys,xs=np.where(I==ocol)
        r0,r1,c0,c1=ys.min(),ys.max(),xs.min(),xs.max()
        mask=(I[r0:r1+1,c0:c1+1]==ocol)
        bi=bands.index([rr for rr in bands[0]] if False else None)  # placeholder removed below
        bi=[i for i,b in enumerate(bands) if b[0]<=r0<=b[1]][0]
        nb=bands[len(bands)-1-bi]
        nrc=W-1-c1
        for i in range(mask.shape[0]):
            for j in range(mask.shape[1]):
                if mask[i,j]:
                    out[nb[0]+i, nb[1]+(mask.shape[1]-1-j)]=ocol
    return out.tolist()

